create extension if not exists pgcrypto;
create type public.user_role as enum ('admin','teacher','student');
create type public.question_type as enum ('mcq_single','mcq_multi','true_false');
create type public.complaint_status as enum ('open','in_review','resolved','rejected');
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end $$;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,email text not null unique,role public.user_role not null,roll_no text unique,is_active boolean not null default true,must_change_password boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.courses(id uuid primary key default gen_random_uuid(),code text not null unique,title text not null,description text,is_archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.course_teachers(course_id uuid not null references public.courses(id) on delete cascade,teacher_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(course_id,teacher_id));
create table public.enrollments(course_id uuid not null references public.courses(id) on delete cascade,student_id uuid not null references public.profiles(id) on delete cascade,enrolled_at timestamptz not null default now(),created_at timestamptz not null default now(),primary key(course_id,student_id));
create index enrollments_student_idx on public.enrollments(student_id);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='admin' and is_active)$$;
create or replace function public.teaches(target_course uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from course_teachers where course_id=target_course and teacher_id=auth.uid())$$;
create or replace function public.is_enrolled(target_course uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from enrollments where course_id=target_course and student_id=auth.uid())$$;
create or replace function public.is_course_member(target_course uuid) returns boolean language sql stable security definer set search_path=public as $$select public.is_admin() or public.teaches(target_course) or public.is_enrolled(target_course)$$;
create or replace function public.teaches_profile(target_user uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from course_teachers ct where ct.teacher_id=auth.uid() and (exists(select 1 from course_teachers other where other.course_id=ct.course_id and other.teacher_id=target_user) or exists(select 1 from enrollments en where en.course_id=ct.course_id and en.student_id=target_user)))$$;
create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at();create trigger courses_updated before update on public.courses for each row execute function public.set_updated_at();
alter table public.profiles enable row level security;alter table public.courses enable row level security;alter table public.course_teachers enable row level security;alter table public.enrollments enable row level security;
create policy profiles_read_self_or_admin on public.profiles for select using(id=auth.uid() or public.is_admin() or public.teaches_profile(id));create policy profiles_admin_manage on public.profiles for all using(public.is_admin()) with check(public.is_admin());
create policy courses_visible on public.courses for select using(public.is_admin() or public.teaches(id) or (public.is_enrolled(id) and not is_archived));create policy courses_admin_manage on public.courses for all using(public.is_admin()) with check(public.is_admin());
create policy course_teachers_visible on public.course_teachers for select using(public.is_admin() or teacher_id=auth.uid() or public.is_course_member(course_id));create policy course_teachers_admin_manage on public.course_teachers for all using(public.is_admin()) with check(public.is_admin());
create policy enrollments_visible on public.enrollments for select using(public.is_admin() or student_id=auth.uid() or public.teaches(course_id));create policy enrollments_admin_manage on public.enrollments for all using(public.is_admin()) with check(public.is_admin());
